CREATE OR REPLACE FUNCTION public.rpc_get_ops_alerts(p_statuses text[] DEFAULT NULL::text[], p_resolved_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now TIMESTAMPTZ := NOW();
